package nro.models.Bot;
import java.sql.*;import java.util.*;import java.nio.file.*;import nro.models.data.LocalManager;import nro.models.item.Item;import nro.models.map.ItemMap;import nro.models.mob.Mob;import nro.models.server.*;import nro.models.player_system.Template.*;import nro.models.services.*;import nro.models.skill.*;import nro.models.boss.Nappa.Kuku;import nro.models.boss.Boss_Manager.BossManager;import nro.models.consts.BossStatus;
public class TrialBotsTest {
 static int checks;static void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);checks++;System.out.println("PASS: "+msg);}
 static nro.models.map.Map map(int id){var m=new nro.models.map.Map(id,"Bot QA",(byte)0,(byte)0,(byte)0,(byte)0,(byte)0,new int[24][60],new int[]{0},1,20,new ArrayList<>());Manager.MAPS.add(m);return m;}
 static class Target extends Mob {int hits;Target(nro.models.map.Zone zone){this.zone=zone;tempId=1;point.hp=point.maxHp=500;location.x=200;location.y=100;zone.mobs.add(this);}public void injured(nro.models.player.Player p,long damage,boolean full){point.hp=Math.max(0,point.hp-(int)damage);hits++;}}
 static void skills(Connection c)throws Exception{for(int g=0;g<3;g++){NClass n=new NClass();n.classId=(byte)g;Manager.NCLASS.add(n);int id=g==0?0:g==1?2:4;try(var q=c.prepareStatement("SELECT * FROM skill_template WHERE id=?")){q.setInt(1,id);try(var r=q.executeQuery()){if(!r.next())throw new AssertionError("missing skill");SkillTemplate t=new SkillTemplate();t.id=(byte)id;t.classId=(byte)g;t.type=r.getByte("type");t.manaUseType=r.getByte("mana_use_type");n.skillTemplatess.add(t);var rows=(org.json.simple.JSONArray)org.json.simple.JSONValue.parse(r.getString("skills").replaceAll("\\[\"","[").replaceAll("\"\\[","[").replaceAll("\"\\]","]").replaceAll("\\]\"","]").replaceAll("\\}\",\"\\{","},{"));for(Object row:rows){var o=(org.json.simple.JSONObject)org.json.simple.JSONValue.parse(String.valueOf(row));Skill s=new Skill();s.template=t;s.skillId=Short.parseShort(o.get("id").toString());s.point=Integer.parseInt(o.get("point").toString());s.damage=Short.parseShort(o.get("damage").toString());s.coolDown=Integer.parseInt(o.get("cool_down").toString());s.manaUse=Integer.parseInt(o.get("mana_use").toString());s.maxFight=1;t.skillss.add(s);}}}}}
 public static void main(String[] args)throws Exception{try{
  try(Connection c=LocalManager.getConnection();Statement q=c.createStatement()){
   check(java.util.Set.of("nro_panel_qa_20261013","nro_teamobi_qa_20261017_v2","nro_teamobi_qa_20261017_v3").contains(c.getCatalog()),"QA database guard");
   try(ResultSet r=q.executeQuery("SELECT * FROM item_template ORDER BY id")){while(r.next())Manager.ITEM_TEMPLATES.add(new ItemTemplate(r.getShort("id"),r.getByte("type"),r.getByte("gender"),r.getString("name"),r.getString("description"),r.getShort("icon_id"),r.getShort("part"),r.getBoolean("is_up_to_up"),0));}
   try(ResultSet r=q.executeQuery("SELECT * FROM item_option_template ORDER BY id")){while(r.next())Manager.ITEM_OPTION_TEMPLATES.add(new ItemOptionTemplate(r.getInt("id"),r.getString("name"),0));}skills(c);
  }
  var z1=map(1).zones.get(0);var z2=map(2).zones.get(0);var z8=map(8).zones.get(0);var z15=map(15).zones.get(0);var z79=map(79).zones.get(0);map(154);
  Target m=new Target(z1);new Target(z2);new Target(z8);new Target(z15);
  TrialBot farm=new TrialBot(TrialBot.Mode.FARM,1);check(farm.isBot&&!farm.isPl()&&farm.getSession()==null,"bot has no account/session and cannot receive VNĐ bounty");check(farm.inventory.itemsBag.size()==100&&farm.inventory.itemsBody.size()==11,"bot bag stays within client100 slot limit");check(farm.playerSkill.skills.size()==1&&farm.playerSkill.skillSelect.template.id==0,"bot loads actual class punch skill");
  long now=System.currentTimeMillis();farm.farmRoute(now);check(farm.zone==z1,"farm enters allowed route");long power=farm.nPoint.power;
  farm.location.x=900;farm.location.y=400;farm.tick(now);
  check(m.hits==1&&Math.abs(farm.location.x-m.location.x)<=70&&Math.abs(farm.location.y-m.location.y)<=70,"TDLT closes distant gap and uses real skill in same attack tick");
  int firstHits=m.hits;int firstMp=farm.nPoint.mp;farm.tick(now+1);
  check(m.hits==firstHits&&farm.nPoint.mp==firstMp,"TDLT repeated tick respects skill cooldown and does not spend extra KI");
  farm.playerSkill.skillSelect.lastTimeUseThisSkill=0;farm.nPoint.mp=0;farm.tick(now+2000);
  check(m.hits==firstHits,"TDLT cannot attack without KI");farm.nPoint.mp=firstMp;
  for(int i=2;i<17&&!m.isDie();i++){farm.playerSkill.skillSelect.lastTimeUseThisSkill=0;farm.tick(now+i*2000);}
  check(m.hits>0&&m.isDie()&&farm.attacks>0&&farm.kills==1,"real SkillService attack damages and defeats mob");check(farm.nPoint.power>power&&farm.nPoint.tiemNang>0,"farm gains simulation power and potential");
  farm.location.x=200;farm.location.y=100;ItemMap own=new ItemMap(z1,220,1,200,100,farm.id),foreign=new ItemMap(z1,221,1,200,100,999),publicLoot=new ItemMap(z1,222,1,200,100,-1);farm.pickup();check(own.isPickedUp&&farm.pickups==1,"bot actually picks owned item");check(!foreign.isPickedUp&&!publicLoot.isPickedUp,"bot leaves other players and public loot untouched");
  for(int i=0;i<farm.inventory.itemsBag.size();i++)farm.inventory.itemsBag.set(i,ItemService.gI().createNewItem((short)650));ItemMap full=new ItemMap(z1,223,1,200,100,farm.id);farm.pickup();check(!full.isPickedUp&&z1.items.contains(full),"full bag keeps item on ground without fake removal");
  long goldBefore=farm.inventory.gold;int gemBefore=farm.inventory.gem;
  ItemMap goldDrop=new ItemMap(z1,76,500,200,100,farm.id),gemDrop=new ItemMap(z1,77,10,200,100,farm.id);
  var stderr=new java.io.ByteArrayOutputStream();var originalErr=System.err;try{System.setErr(new java.io.PrintStream(stderr));farm.pickup();}finally{System.setErr(originalErr);}
  check(goldDrop.isPickedUp&&gemDrop.isPickedUp&&farm.inventory.gold==goldBefore+500&&farm.inventory.gem==gemBefore+10,"sessionless bot picks actual gold and gems");
  check(!stderr.toString().contains("NullPointerException"),"currency pickup produces no null-session error log");
  farm.nPoint.hp=0;farm.tick(now+40000);check(farm.nPoint.hp==0,"dead bot waits instead of instant revive");farm.tick(now+69999);check(farm.nPoint.hp==0,"revive cooldown lasts30 seconds");farm.tick(now+70001);check(farm.nPoint.hp>0,"bot revives after30 seconds");check(farm.zone==z2,"revived bot can move to next allowed map");
  check(!TrialBot.allowedFarmMap(154)&&!TrialBot.allowedFarmMap(21)&&TrialBot.allowedFarmMap(8),"farm excludes home and private maps");
  Kuku boss=new Kuku();boss.zone=z79;boss.bossStatus=BossStatus.ACTIVE;boss.nPoint.hp=boss.nPoint.hpMax=1000000;boss.nPoint.dame=1000;boss.location.x=200;boss.location.y=100;boss.typePk=nro.models.consts.ConstPlayer.PK_ALL;boss.name="Kuku QA";check(TrialBot.eligibleBoss(boss),"live combat boss on open map qualifies");boss.zone=Manager.MAPS.stream().filter(x->x.mapId==154).findFirst().get().zones.get(0);check(!TrialBot.eligibleBoss(boss),"boss in private/training map excluded");boss.zone=z79;boss.bossStatus=BossStatus.CHAT_S;check(!TrialBot.eligibleBoss(boss),"boss still talking cannot be targeted");boss.bossStatus=BossStatus.ACTIVE;boss.nPoint.hpMax=300000000;check(!TrialBot.eligibleBoss(boss),"trial skips overly strong boss");boss.nPoint.hpMax=1000000;
  TrialBot hunter=new TrialBot(TrialBot.Mode.HUNT,1);hunter.tick(now+80000);check(hunter.zone==z79&&hunter.activity.contains("Kuku"),"hunter finds actual boss and changes map");int bossHp=boss.nPoint.hp;
  for(int i=1;i<=4;i++){hunter.playerSkill.skillSelect.lastTimeUseThisSkill=0;hunter.tick(now+80000+i*2000);if(hunter.attacks>0)break;}
  check(hunter.attacks>0&&boss.nPoint.hp<bossHp,"hunter uses actual SkillService to damage combat boss");
  boss.zone=null;hunter.tick(now+96000);check(hunter.errors==0,"boss leaving map handled without deleting bot");BossManager.gI().removeBoss(boss);
  Path dir=Files.createTempDirectory("trial-bots-qa-");TrialBots service=new TrialBots(dir.resolve("bots.properties"),dir.resolve("status.json"));service.configure(true);check(service.snapshot().size()==3,"trial creates exactly3 bots");check(service.snapshot().stream().filter(b->b.mode==TrialBot.Mode.FARM).count()==2&&service.snapshot().stream().filter(b->b.mode==TrialBot.Mode.HUNT).count()==1,"two farmers and one hunter");var ids=service.snapshot().stream().map(b->b.id).toList();service.tick();check(ids.equals(service.snapshot().stream().map(b->b.id).toList()),"repeated ticks do not duplicate bots");check(Files.exists(dir.resolve("status.json")),"status snapshot written");service.configure(false);check(service.snapshot().isEmpty(),"disable stops all trial bots");check(Manager.MAPS.stream().flatMap(w->w.zones.stream()).flatMap(z->z.getHumanoids().stream()).noneMatch(p->ids.contains(p.id)),"disabled bots removed from map lists");
  farm.stop();hunter.stop();check(farm.zone==null&&hunter.zone==null,"stop detaches independent bots");
  System.out.println("PASS: "+checks+" trial bot checks");
 }finally{LocalManager.close();}System.exit(0);}
}
